#include <bits/stdc++.h>
using namespace std;

int binarySearch(const vector<int>& a, int target) {
    int left = 0;
    int right = (int)a.size() - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (a[mid] == target)
            return mid;

        if (a[mid] < target)
            left = mid + 1;
        else
            right = mid - 1;
    }

    return -1;
}

int main() {
    vector<int> a = {1, 3, 5, 7, 9};

    cout << binarySearch(a, 7) << '\n';
    cout << binarySearch(a, 6) << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int lowerBound(const vector<int>& a, int target) {
    int left = 0;
    int right = (int)a.size();

    while (left < right) {
        int mid = left + (right - left) / 2;

        if (a[mid] >= target)
            right = mid;
        else
            left = mid + 1;
    }

    return left;
}

int main() {
    vector<int> a = {1, 2, 2, 2, 5, 7};

    cout << lowerBound(a, 2) << '\n';
    cout << lowerBound(a, 4) << '\n';
    cout << lowerBound(a, 8) << '\n';

    return 0;
}

