#include <bits/stdc++.h>
using namespace std;

bool check(long long mid, const vector<long long>& a, long long k) {
    long long need = 0;
    int n = (int)a.size();

    for (int i = n / 2; i < n; ++i) {
        if (a[i] < mid) {
            need += mid - a[i];
            if (need > k)
                return false;
        }
    }

    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    cin >> n >> k;

    vector<long long> a(n);
    for (long long& x : a)
        cin >> x;

    sort(a.begin(), a.end());

    long long left = a[n / 2];
    long long right = a[n / 2] + k;

    while (left < right) {
        long long mid = left + (right - left + 1) / 2;

        if (check(mid, a, k))
            left = mid;
        else
            right = mid - 1;
    }

    cout << left << '\n';

    return 0;
}

