    int x = 2;

    int first = lower_bound(a.begin(), a.end(), x) - a.begin();
    int after = upper_bound(a.begin(), a.end(), x) - a.begin();

    cout << "first = " << first << '\n';
    cout << "after = " << after << '\n';
    cout << "count = " << after - first << '\n';

